// Deux entrees possibles : la scrutation Gmail, ou la porte de rejeu. On lit
// donc les declencheurs par leur NOM, et on tolere que l'un des deux n'ait pas
// tourne : $('...') sur un noeud non execute leve, d'ou le try/catch.
// Rappel du piege : dans un noeud Code, $json est la sortie du PREDECESSEUR
// immediat (ici Config), pas celle du declencheur.
const lire = (nom) => { try { return $(nom).all(); } catch (e) { return []; } };
const msgs = [...lire('📬 Gmail: nouveaux messages'), ...lire('📥 Gmail: messages a rejouer')];
const cfg = $('⚙️ Config WF4').first().json;
const moi = String(cfg.lineoEmail || '').trim().toLowerCase();

const sansAccents = (v) => String(v || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '').toLowerCase();

const texteDe = (m) => {
  const t = String(m.text || '');
  if (t.trim()) return t;
  const h = String(m.html || m.textAsHtml || '');
  return h.replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
};

// ── Preuves TECHNIQUES d un envoi automatique ────────────────────────────
// RFC 3834 pour Auto-Submitted, plus les en-tetes de fait des repondeurs.
// Un en-tete ne se trompe pas sur son propre compte : c est ce qui permettra
// de verrouiller le verdict « accuse de reception » contre le classificateur.
const ENTETES_AUTO = ['x-autoreply', 'x-autorespond', 'x-autoresponse', 'x-auto-response-suppress'];
const PHRASES_AUTO = [
  'reponse automatique', 'message automatique', 'ceci est un message automatique',
  'ne pas repondre a ce message', 'merci de ne pas repondre', 'ne repondez pas a ce message',
  'absence du bureau', 'je suis actuellement absent', 'suis absent du bureau',
  'out of office', 'automatic reply', 'auto-reply', 'autoreply', 'do not reply to this message',
];
// Accuse « doux » : la reception est confirmee, rien de plus. Il ne tranche PAS
// seul, parce quun refus commence souvent par « nous avons bien recu votre
// candidature ». Il ne sert que de repli si le classificateur est muet.
const PHRASES_ACCUSE = [
  'accuse de reception', 'nous avons bien recu', 'nous avons bien receptionne',
  'votre candidature a bien ete recue', 'votre candidature a ete recue',
  'candidature bien recue', 'nous confirmons la reception', 'nous accusons reception',
  'we have received your application', 'thank you for applying', 'application received',
  'your application has been received',
];
const PHRASES_REFUS = [
  'ne donnons pas suite', 'ne donnerons pas suite', 'ne pas donner suite',
  'na pas ete retenue', 'navons pas retenu', 'ne retenons pas votre candidature',
  'ne correspond pas au profil', 'ne correspond pas a nos besoins',
  'poste a ete pourvu', 'offre est pourvue', 'processus est clos', 'nous regrettons',
  'malheureusement', 'unfortunately', 'not a match', 'will not be moving forward',
  'position has been filled',
];
const PHRASES_ENTRETIEN = [
  'entretien', 'vous rencontrer', 'echange telephonique', 'un premier echange',
  'vos disponibilites', 'etes vous disponible', 'convenir dun creneau',
  'planifier un appel', 'en visio', 'interview', 'phone screen', 'schedule a call',
];

const sortie = [];
const vus = new Set();
for (const it of msgs) {
  const m = it.json ?? {};
  const id = String(m.id ?? '');
  // Rejeu et scrutation peuvent ramener le meme message : on ne le traite quune fois.
  if (!id || vus.has(id)) continue;
  vus.add(id);

  const entetes = {};
  for (const [k, v] of Object.entries(m.headers ?? {})) entetes[String(k).toLowerCase()] = String(v ?? '');

  const expediteur = String(m.from?.value?.[0]?.address ?? '').trim().toLowerCase();
  const local = expediteur.split('@')[0] || '';
  const domaine = expediteur.split('@')[1] || '';

  // Un message de Lineo lui-meme nest jamais une reponse de recruteur : ni ses
  // propres candidatures, ni ses relances, ni les notifications de ce workflow.
  if (!expediteur || (moi && expediteur === moi)) continue;

  const objet = String(m.subject ?? '');
  const corps = texteDe(m).slice(0, 4000);
  const plat = sansAccents(objet + ' | ' + corps);

  const preuves = [];
  const auto = entetes['auto-submitted'] || '';
  if (auto && auto.toLowerCase() !== 'no') preuves.push('Auto-Submitted: ' + auto);
  for (const h of ENTETES_AUTO) if (entetes[h]) preuves.push(h + ': ' + entetes[h]);
  const prec = (entetes['precedence'] || '').toLowerCase();
  if (prec === 'bulk' || prec === 'auto_reply' || prec === 'junk' || prec === 'list') preuves.push('Precedence: ' + prec);
  if (/^(no-?reply|noreply|donotreply|do-not-reply|ne-?pas-?repondre|nepasrepondre|mailer-daemon|postmaster|notifications?|automat)/.test(local)) {
    preuves.push('expediteur technique : ' + local);
  }
  for (const p of PHRASES_AUTO) if (plat.includes(p)) preuves.push('formule de repondeur : ' + p);

  sortie.push({
    json: {
      messageId: id,
      filGmail: String(m.threadId ?? ''),
      expediteur,
      expediteurNom: String(m.from?.value?.[0]?.name ?? '').trim(),
      expediteurDomaine: domaine,
      objet,
      recuLe: String(m.date ?? entetes['date'] ?? ''),
      corps,
      extrait: corps.replace(/\s+/g, ' ').trim().slice(0, 900),
      accuseTechnique: preuves.length > 0,
      preuvesTechniques: preuves,
      accuseDoux: PHRASES_ACCUSE.filter((p) => plat.includes(p)),
      indicesRefus: PHRASES_REFUS.filter((p) => plat.includes(p)),
      indicesEntretien: PHRASES_ENTRETIEN.filter((p) => plat.includes(p)),
      lienGmail: 'https://mail.google.com/mail/u/0/#all/' + String(m.threadId ?? ''),
    },
  });
}

// Zero message a traiter est letat NORMAL dune scrutation : la chaine sarrete
// la, le prochain passage reprendra. Rien a signaler, rien a inventer.
return sortie;

// Le detail des decisions est dans les courriels de notification et dans le
// journal de lexecution : ce noeud ne recalcule rien, il clot la tournee.
const examines = $('🧩 Messages: normaliser').all().length;
return [{ json: { schema: 'wf4-bilan/v1', messages_examines: examines, termine_le: new Date().toISOString() } }];

const cfg = $('⚙️ Config WF4').first().json;
const msg = $('🔁 Boucle messages').first().json;
const app = $('🐘 Postgres: apparier la candidature').first().json;
const rep = $input.first().json ?? {};

// Le slug de WF3, au caractere pres. Le copier est volontaire : cest un
// CONTRAT entre deux workflows, pas une commodite locale.
const slug = (v) => String(v || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '').slice(0, 40);
const aplati = (v) => String(v || '')
  .normalize('NFD').replace(/\p{Diacritic}/gu, '')
  .toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// ── Cadence : la config career-ops fait loi, les valeurs de Config sont un repli
const entries = Array.isArray(rep.entries) ? rep.entries : [];
const cc = rep.cadenceConfig ?? rep.metadata?.cadenceConfig ?? {};
const premierEntier = (...valeurs) => {
  for (const v of valeurs) {
    const n = Number(v);
    if (Number.isFinite(n) && n > 0) return Math.floor(n);
  }
  return null;
};
const relanceDelaiJours = premierEntier(cc.applied_first_days, cc.appliedFirstDays, cc.applied_first, cc.first_days, cfg.relanceSeuilJoursRepli, 7);
const relanceMax = premierEntier(cc.applied_max_followups, cc.appliedMaxFollowups, cc.max_followups, cc.applied_max, cfg.relanceMaxRepli, 2);
const cadenceSource = premierEntier(cc.applied_first_days, cc.appliedFirstDays, cc.applied_first, cc.first_days)
  ? 'config career-ops (/api/followups?full=1)'
  : 'repli : valeurs par defaut documentees';
const followupsErreur = (rep.entries === undefined && rep.due === undefined)
  ? ('GET /api/followups injoignable ou hors contrat : ' + JSON.stringify(rep).slice(0, 200))
  : '';

// ── La cle de deduplication des relances ────────────────────────────────
const entrepriseSql = String(app.entreprise || '').trim();
const posteSql = String(app.poste || '').trim();
const cible = aplati(entrepriseSql);
let entree = null;
for (const e of entries) {
  const c = aplati(e.company);
  if (!c || !cible) continue;
  if (c === cible || c.includes(cible) || cible.includes(c)) { entree = e; break; }
}
const entreprise = entree ? String(entree.company || '').trim() : entrepriseSql;
const poste = entree ? String(entree.role || '').trim() : posteSql;
const cleSource = entree
  ? 'tracker career-ops (meme source que WF3)'
  : 'projection Postgres : aucune ligne de tracker appariee, la cle peut differer de celle de WF3';
const relanceId = 'relance-' + (slug(entreprise) || 'entreprise') + '-' + (slug(poste) || 'poste');

// ── Le prompt du classificateur local ───────────────────────────────────
const consigne = [
  'Tu classes UN courriel recu en reponse a une candidature. Reponds UNIQUEMENT par un objet JSON, sans texte autour et sans balise de code.',
  '',
  'Schema exact attendu :',
  '{"type":"<valeur>","confiance":"haute|moyenne|basse","resume":"<une phrase en francais, 200 caracteres maxi>"}',
  '',
  'Valeurs possibles pour type :',
  '- accuse_reception : confirmation automatique de reception, message de robot, absence du bureau. AUCUNE personne ne sest prononcee sur la candidature.',
  '- refus : la candidature nest pas retenue, le poste est pourvu, le processus est clos.',
  '- entretien : on propose ou on demande un entretien, un echange, des disponibilites.',
  '- offre : une proposition ou une promesse dembauche.',
  '- reponse_humaine : une personne repond vraiment (question, demande de piece, mise en attente explicite) sans etre un des cas ci-dessus.',
  '- hors_sujet : le message ne parle pas de cette candidature (publicite, alerte emploi, infolettre, facture).',
  '',
  'REGLE IMPERATIVE : au moindre doute entre accuse_reception et un autre type, choisis accuse_reception et mets confiance basse. Un accuse de reception classe comme une vraie reponse arreterait A TORT les relances, et cest la pire erreur possible ici.',
  '',
  'Candidature concernee : ' + (entreprise || 'inconnue') + ' / ' + (poste || 'poste inconnu'),
  'Expediteur : ' + String(msg.expediteurNom || '') + ' <' + String(msg.expediteur || '') + '>',
  'Objet : ' + String(msg.objet || ''),
  'Corps :',
  String(msg.corps || '').slice(0, 3500),
].join('\n');

return [{
  json: {
    ...msg,
    candidatureId: String(app.candidature_id || ''),
    indiceAppariement: String(app.indice || ''),
    candidatsAppariement: Number(app.candidats || 0),
    brancheGithub: String(app.branche_github || ''),
    courrielContact: String(app.courriel_contact || ''),
    urlOffre: String(app.url_offre || ''),
    candidatureEnvoyeeLe: String(app.envoyee_le || ''),
    entreprise, poste, entrepriseSql, posteSql,
    trackerNum: entree ? String(entree.num ?? '') : '',
    relanceId,
    cleSource,
    histPath: 'data-inbox/relances/' + relanceId + '.json',
    relanceDelaiJours, relanceMax, cadenceSource, followupsErreur,
    llmBodyRaw: JSON.stringify({ model: 'career-ops-cli', stream: false, messages: [{ role: 'user', content: consigne }] }),
  },
}];

const ctx = $('🧩 Reponse: contexte et cle de relance').first().json;
const brut = $input.first().json ?? {};

// ── Ce que le classificateur a rendu, ou pourquoi il na rien rendu ──────
let llmType = '';
let llmConfiance = '';
let llmResume = '';
let llmErreur = '';
const contenu = brut?.choices?.[0]?.message?.content;
if (typeof contenu === 'string' && contenu.trim()) {
  const t = contenu.replace(/```json/gi, '').replace(/```/g, '').trim();
  const d = t.indexOf('{');
  const f = t.lastIndexOf('}');
  try {
    const j = JSON.parse(t.slice(d, f + 1));
    llmType = String(j.type || '').trim().toLowerCase();
    llmConfiance = String(j.confiance || '').trim().toLowerCase();
    llmResume = String(j.resume || '').trim().slice(0, 300);
  } catch (e) {
    llmErreur = 'reponse du classificateur illisible : ' + String(contenu).slice(0, 200);
  }
} else {
  llmErreur = 'le classificateur local na rien rendu : ' + JSON.stringify(brut).slice(0, 200);
}
const TYPES = ['accuse_reception', 'refus', 'entretien', 'offre', 'reponse_humaine', 'hors_sujet'];
if (llmType && !TYPES.includes(llmType)) {
  llmErreur = llmErreur || ('type hors schema rendu par le classificateur : ' + llmType);
  llmType = '';
}

// ── PRECEDENCE ──────────────────────────────────────────────────────────
// 1. Preuve technique daccuse de reception : VERROUILLE. Un en-tete
//    Auto-Submitted, un expediteur no-reply ou une formule de repondeur ne
//    se discutent pas, et surtout pas avec un modele de langue.
// 2. Sinon le classificateur.
// 3. Sinon un repli deterministe, qui dit quil est un repli.
// 4. Sinon : indetermine. On narrete rien et on le signale.
let type = '';
let source = '';
if (ctx.accuseTechnique) {
  type = 'accuse_reception';
  source = 'preuve technique (en-tetes / expediteur / formule) : verdict verrouille, classificateur ignore';
} else if (llmType) {
  type = llmType;
  source = 'classificateur local career-ops';
} else if ((ctx.indicesEntretien || []).length && !(ctx.indicesRefus || []).length) {
  type = 'entretien';
  source = 'repli deterministe : classificateur indisponible';
} else if ((ctx.indicesRefus || []).length) {
  type = 'refus';
  source = 'repli deterministe : classificateur indisponible';
} else if ((ctx.accuseDoux || []).length) {
  type = 'accuse_reception';
  source = 'repli deterministe : classificateur indisponible';
} else {
  type = 'indetermine';
  source = 'aucun verdict : ni preuve technique, ni classificateur, ni indice';
}

// ── Arret des relances ──────────────────────────────────────────────────
// Seuls ces quatre types sont une REPONSE. accuse_reception, hors_sujet et
// indetermine narretent RIEN : cest la regle 1, prise au mot.
const ARRETENT = { refus: 'Rejected', entretien: 'Interview', offre: 'Offer', reponse_humaine: 'Responded' };
const statutTracker = ARRETENT[type] || '';
const arret = Boolean(statutTracker);
const LIBELLES = {
  accuse_reception: 'accuse de reception automatique',
  refus: 'refus',
  entretien: 'proposition dentretien',
  offre: 'proposition dembauche',
  reponse_humaine: 'reponse humaine',
  hors_sujet: 'hors sujet',
  indetermine: 'indetermine',
};
const typeLibelle = LIBELLES[type] || type;
const arreteLe = new Date().toISOString();
const motifArret = arret ? ('reponse du recruteur : ' + typeLibelle) : '';

// Le tracker est le SEUL point decriture sanctionne de data/applications.md, et
// les statistiques sen derivent (analyze-patterns.mjs, /stats, /analytics).
// Rien nest recalcule ici, et il ne faut pas y toucher : ecrire la ligne suffit.
const note = ('reponse ' + type + ' recue le ' + String(ctx.recuLe || arreteLe) + ' de ' + String(ctx.expediteur || '') + ' (workflow 4, fil ' + String(ctx.filGmail || '') + ')').slice(0, 300);
const trackerBodyRaw = JSON.stringify({
  entreprise: ctx.entreprise, statut: statutTracker, role: ctx.poste, note,
});

return [{
  json: {
    ...ctx,
    type, typeLibelle, arret, statutTracker, motifArret, arreteLe,
    verdictSource: source,
    llmType, llmConfiance, llmResume, llmErreur,
    // Le classificateur a vu une formule daccuse de reception et a quand meme
    // tranche autrement : ca se dit dans la notification, ca ne se cache pas.
    tensionAccuse: Boolean((ctx.accuseDoux || []).length && type !== 'accuse_reception' && !ctx.accuseTechnique),
    resume: llmResume,
    trackerBodyRaw,
  },
}];

const cfg = $('⚙️ Config WF4').first().json;
const v = $('🧩 Reponse: verdict').first().json;
const prev = $input.first().json ?? {};

if (!v.relanceId) {
  throw new Error('verdict sans relanceId : rien ne serait ecrit et les relances repartiraient sans que personne le sache');
}

let histoire = null;
let sha = null;
if (typeof prev.sha === 'string' && prev.sha) {
  sha = prev.sha;
  try {
    const lu = JSON.parse(Buffer.from(String(prev.content || '').replace(/\n/g, ''), 'base64').toString('utf8'));
    if (lu && typeof lu === 'object') histoire = lu;
  } catch (e) {
    // Fiche illisible : on la remplace plutot que de bloquer larret. Perdre
    // lhistorique est moins grave que laisser les relances repartir.
    histoire = null;
  }
}
const relances = Array.isArray(histoire?.relances) ? histoire.relances : [];

const fiche = {
  schema: 'career-ops-relances/v1',
  id: v.relanceId,
  entreprise: v.entreprise,
  poste: v.poste,
  courriel_contact: v.courrielContact || null,
  url_offre: v.urlOffre || null,
  cadence: {
    espacement_jours: v.relanceDelaiJours,
    maximum: v.relanceMax,
    source: v.cadenceSource,
  },
  relances,
  // LE champ qui arrete tout. « Relance: decider » doit le lire en TOUT PREMIER,
  // avant le plafond et avant lespacement.
  arret: {
    actif: true,
    motif: v.motifArret,
    type_reponse: v.type,
    arrete_le: v.arreteLe,
    source: 'workflow 4 : ecoute Gmail des reponses',
    verdict_source: v.verdictSource,
    resume: v.resume || null,
    message_gmail_id: v.messageId,
    fil_gmail: v.filGmail,
    expediteur: v.expediteur,
    objet: v.objet,
    indice_appariement: v.indiceAppariement,
    cle_source: v.cleSource,
    candidature_id: v.candidatureId || null,
    branche_github: v.brancheGithub || null,
    statut_tracker: v.statutTracker,
    execution_id: String($execution.id),
  },
};

const body = {
  message: 'chore(relances): arret ' + (v.entreprise || 'entreprise') + ' (' + v.type + ')',
  content: Buffer.from(JSON.stringify(fiche, null, 2) + '\n', 'utf8').toString('base64'),
  branch: cfg.githubBaseBranch,
};
if (sha) body.sha = sha;

return [{ json: { ...v, histSha: sha, relancesConservees: relances.length, arretBodyRaw: JSON.stringify(body) } }];
